// ── 플라이오버(지도의 시선) ──
//    본촬영(2026-10-25)은 0~21.09km 전 구간에 컷이 있어 메울 공백이 없다.
//    영상은 인트로 배경으로 쓰고, km↔시각 보정식은 스크럽용으로 남겨둔다.
const FLY='web/flyover.mp4';
const PH=D.photos.slice().sort((a,b)=>a.km-b.km);
// 같은 자리에서 찍은 컷 묶음. 거리가 같으면 능선 위 한 점에 겹쳐서,
// 드래그로는 맨 앞 컷만 잡히고 나머지(사진 옆의 영상 등)는 못 보게 된다.
// 한 점으로 병합해 두고, 그 점을 다시 누르면 묶인 컷을 차례로 넘긴다.
const STACK=(()=>{const m={};PH.forEach((p,i)=>{(m[p.km]=m[p.km]||[]).push(i);});return m;})();
function stackOf(i){return STACK[PH[i].km]||[i];}
// 이미지/영상 로드 실패 시 쓰는 대체(fallback) 이미지 — base64 인라인.
const FB="data:image/jpeg;base64,";
// ── 캔버스 & 오프스크린 버퍼 ─────────────────────────────────────
//  화면 캔버스(cv)와 숨겨진 <video>. 렌더는 오프스크린 버퍼에 미리 만든 뒤
//  글리치 효과로 합성한다: baseC(색보정 원본) / redC·cyanC(RGB 채널 분리본).
const cv=document.getElementById('cv'),ctx=cv.getContext('2d'),vid=document.getElementById('vid');
let W,H,DPR,baseC,baseX,redC,redX,cyanC,cyanX,baseReady=false,burst=0;
const fbImg=new Image();fbImg.src=FB;
const imgCache={};
function mkC(){const c=document.createElement('canvas');c.width=W;c.height=H;return[c,c.getContext('2d')];} // 오프스크린 캔버스 생성
// 이미지/영상을 화면 비율에 맞게 꽉 채워(cover) 그리기
function drawCover(x,el){const iw=el.videoWidth||el.width||W,ih=el.videoHeight||el.height||H,s=Math.max(W/iw,H/ih),w=iw*s,h=ih*s;x.drawImage(el,(W-w)/2,(H-h)/2,w,h);}
// 필름 느낌 색보정(세피아·시안·명암 레이어를 합성)
function grade(x){x.globalCompositeOperation='multiply';x.fillStyle='rgba(58,44,26,.34)';x.fillRect(0,0,W,H);
  x.globalCompositeOperation='screen';x.fillStyle='rgba(18,44,52,.20)';x.fillRect(0,0,W,H);
  x.globalCompositeOperation='overlay';x.fillStyle='rgba(0,0,0,.22)';x.fillRect(0,0,W,H);x.globalCompositeOperation='source-over';}
// 소스(el)로부터 오프스크린 버퍼 3종(base·red·cyan) 재생성 — 컷이 바뀌거나 영상 프레임이 갱신될 때 호출
function rebuild(el){if(!el||(!el.width&&!el.videoWidth))el=fbImg;
  baseX.clearRect(0,0,W,H);drawCover(baseX,el);grade(baseX);
  redX.clearRect(0,0,W,H);redX.drawImage(baseC,0,0);redX.globalCompositeOperation='multiply';redX.fillStyle='#ff4a1e';redX.fillRect(0,0,W,H);redX.globalCompositeOperation='source-over';
  cyanX.clearRect(0,0,W,H);cyanX.drawImage(baseC,0,0);cyanX.globalCompositeOperation='multiply';cyanX.fillStyle='#26dcff';cyanX.fillRect(0,0,W,H);cyanX.globalCompositeOperation='source-over';
  baseReady=true;}
// 창 크기 변화 대응: 캔버스 해상도(DPR 반영) 갱신 + 버퍼 재할당
function resize(){DPR=Math.min(2,devicePixelRatio||1);W=innerWidth;H=innerHeight;cv.width=W*DPR;cv.height=H*DPR;cv.style.width=W+'px';cv.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);
  [baseC,baseX]=mkC();[redC,redX]=mkC();[cyanC,cyanX]=mkC();if(cur>=0)applySource();}
addEventListener('resize',resize);

// ── 현재 컷 소스 로딩 ───────────────────────────────────────────
//  cur = 현재 보고 있는 컷 인덱스. 사진은 web/<n>.jpg, 영상은 web/<n>.mp4 로드.
//  로드 성공 시 rebuild()로 버퍼 갱신, 실패하면 fallback 이미지로 대체.
let cur=-1,mode='p',vidReady=false,intensity=0,started=false;
// ── 플라이오버 시간 ↔ 거리 매핑 ─────────────────────────
//  영상엔 GPS 메타데이터가 없지만, 화면에 km 카운터가 찍혀 있다.
//  프레임별로 그 숫자를 OCR해 얻은 실측 선형식(12점 중 11점 정확히 일치):
//     km = 1.2141·t − 2.4224     →     t = 0.8237·km + 1.995
//  (0km = 2.0초, 21.25km = 19.5초. 앞 2초/뒤 2초는 총계를 띄우는 인트로/아웃트로)
//  → 능선 위 현재 위치에 해당하는 항공뷰 지점으로 시킹. 드래그하면 지도도 같이 스크럽된다.
//  FLY_RATE: 컷 간격(0.7km≈1.22초 분량)을 자동넘김 3.2초에 맞춘 재생속도.
//  몸의 시선(흔들리는 TC 영상)과 달리 지도의 시선은 느리고 매끄럽다.
const FLY_A=0.8237,FLY_B=1.995,FLY_RATE=0.38;
function flyTime(km){return Math.max(0,Math.min(19.5,FLY_B+km*FLY_A));}
function syncFly(p){if(!p)return;
  if(p.t==='f'){vid.playbackRate=FLY_RATE;try{vid.currentTime=flyTime(p.km);}catch(e){}}
  else if(vid.playbackRate!==1){vid.playbackRate=1;}}
function applySource(){const p=PH[cur];if(!p)return;
  if(p.t==='v'||p.t==='f'){mode='video';
    // 'f' = 플라이오버. 공백 구간 컷 7개가 같은 영상을 쓰므로,
    //  이미 로드된 영상이면 리로드 없이 재생 지점만 맞춘다(글리치 burst만 터짐).
    const url=(p.t==='f')?FLY:'web/'+p.n+'.mp4';
    if(vid.dataset.cur===url&&vidReady){syncFly(p);burst=1;if(vid.paused)vid.play().catch(()=>{});return;}
    vid.dataset.cur=url;vidReady=false;
    vid.onloadeddata=()=>{vidReady=true;burst=1;syncFly(PH[cur]);vid.play().catch(()=>{});};
    vid.onerror=()=>{mode='p';rebuild(fbImg);burst=1;};vid.src=url;vid.load();}
  else{mode='p';vidReady=false;vid.dataset.cur='';const c=imgCache[p.n];if(c){rebuild(c);burst=1;}
    else{const im=new Image();im.onload=()=>{imgCache[p.n]=im;if(cur>=0&&PH[cur].n===p.n){rebuild(im);burst=1;}};im.onerror=()=>{if(cur>=0&&PH[cur].n===p.n){rebuild(fbImg);burst=1;}};im.src='web/'+p.n+'.jpg';}}
}
// ── HUD 갱신 ────────────────────────────────────────────────────
//  setPhoto(i): i번 컷으로 이동 — 좌상단 위경도, 하단 거리/심박/고도/타입,
//  주소, 능선 마커까지 한 번에 갱신. hrHex()는 심박값을 색으로 매핑.
const lat=document.getElementById('lat'),lon=document.getElementById('lon'),mkm=document.getElementById('mkm'),mhr=document.getElementById('mhr'),mele=document.getElementById('mele'),mtype=document.getElementById('mtype'),addrEl=document.getElementById('addr'),pn=document.getElementById('pn'),coordEl=document.getElementById('coord'),stimeEl=document.getElementById('stime'),sdateEl=document.getElementById('sdate');
// 우하단 스탬프: 컷마다 실제 촬영시각(p.tm)과 촬영일(p.d)을 그대로 찍는다.
const DATE={10:'2026.10.25',7:'2026.07.12'};
function setPhoto(i){i=Math.max(0,Math.min(PH.length-1,i));if(i===cur)return;cur=i;const p=PH[i];
  applySource();
  lat.textContent=p.lat.toFixed(5);lon.textContent=p.lon.toFixed(5);showAddr(p.lat,p.lon);
  mkm.textContent=p.km.toFixed(1)+'km';mhr.textContent='♥'+p.hr;mele.textContent='↑'+p.ele+'m';
  const g=stackOf(i);mtype.textContent=(p.t==='v'?'▶ 영상':(p.t==='f'?'▲ 지도의 시선':'◻ 사진'))+(g.length>1?' '+(g.indexOf(i)+1)+'/'+g.length:'');mhr.style.color=hrHex(p.hr);
  pn.textContent=(p.t==='f')?'기록 없음':p.n;if(stimeEl)stimeEl.textContent=p.tm;if(sdateEl)sdateEl.textContent=DATE[p.d]||'';moveMarker(p.km);moveMapDot(p);burst=1;}
function hrHex(hr){const t=(hr-120)/60;return t>.6?'#cf4b34':t>.3?'#f0a23c':'#7fa088';}

// ── 역지오코딩 (좌표 → 구·동 주소) ─────────────────────────────
//  카카오맵 Geocoder로 위경도를 행정동 주소로 변환. 캐시 + 300ms 디바운스로
//  드래그 중 과도한 요청 방지. 실패 시 '—' 표시.
const addrCache={};let addrReq=0,geocoder=null;
if(window.kakao&&kakao.maps)kakao.maps.load(()=>{geocoder=new kakao.maps.services.Geocoder();});
function showAddr(la,lo){const key=la.toFixed(4)+','+lo.toFixed(4);
  if(addrCache[key]!==undefined){addrEl.textContent=addrCache[key]||'—';return;}
  const my=++addrReq;
  setTimeout(()=>{if(my!==addrReq)return;if(!geocoder){addrEl.textContent='—';return;}
    geocoder.coord2RegionCode(lo,la,(res,st)=>{if(my!==addrReq)return;
      if(st===kakao.maps.services.Status.OK){const h=res.find(r=>r.region_type==='H')||res[0];
        const s=((h.region_2depth_name||'')+' '+(h.region_3depth_name||'')).trim();
        addrCache[key]=s;addrEl.textContent=s||'—';}
      else{addrCache[key]='';addrEl.textContent='—';}});
  },300);}

// ── 우상단 미니맵 (지도의 시선) ────────────────────────────────
//  외부 지도 타일 없이 실제 GPS 트랙 자체를 그린다(14,607점 → 294점으로 솎음).
//  현재 컷 위치를 점으로 얹어, 능선(고도)과 짝이 되는 평면 시선을 준다.
const mmap=document.getElementById('mmap'),MK=D.map.k;  // k=[minLat,maxLat,minLon,kx*s,s]
function mapXY(la,lo){return [(lo-MK[2])*MK[3],(MK[1]-la)*MK[4]];}
if(mmap){
  mmap.setAttribute('viewBox','-30 -30 1060 '+(D.map.h+60));
  mmap.innerHTML='<path d="'+D.map.p+'" fill="none" stroke="#e6d8b2" stroke-width="1.3" opacity="0.6" vector-effect="non-scaling-stroke" stroke-linejoin="round" stroke-linecap="round"/>'
    +'<circle id="mglow" r="62" fill="#f0a23c" opacity="0.22"/><circle id="mdot" r="30" fill="#f0a23c"/>';
}
const mdot=document.getElementById('mdot');
const mglow=document.getElementById('mglow');
function moveMapDot(p){if(!mdot)return;const q=mapXY(p.lat,p.lon);
  [mdot,mglow].forEach(e=>{if(e){e.setAttribute('cx',q[0].toFixed(0));e.setAttribute('cy',q[1].toFixed(0));}});}

// ── 하단 고도 능선 그래프 ──────────────────────────────────────
//  화면 아래쪽 SVG에 코스 고도 프로파일(능선)을 그리고, 각 사진 위치를
//  심박 색상의 점으로 표시. moveMarker()가 현재 위치 마커를 이동시킨다.
const RT=D.total,rprof=D.prof;
let reMax=Math.max.apply(0,rprof.map(p=>p[1]))+8,reMin=Math.min.apply(0,rprof.map(p=>p[1]))-8;
function rX(km){return km/RT*1000;}
function rY(e){return 88-(e-reMin)/(reMax-reMin)*72;}
function rEleAt(km){if(km<=rprof[0][0])return rprof[0][1];if(km>=rprof[rprof.length-1][0])return rprof[rprof.length-1][1];
  for(let i=1;i<rprof.length;i++){if(rprof[i][0]>=km){const a=rprof[i-1],b=rprof[i],f=(km-a[0])/(b[0]-a[0]||1);return a[1]+f*(b[1]-a[1]);}}return rprof[rprof.length-1][1];}
const rdg=document.getElementById('rdg'),rmarker=document.getElementById('rmarker');
function buildRidge(){
  let path='M'+rprof.map(p=>rX(p[0]).toFixed(1)+','+rY(p[1]).toFixed(1)).join(' L');
  path+=' L'+rX(RT).toFixed(1)+','+rY(rprof[rprof.length-1][1]).toFixed(1);
  // 공백 구간 밴드(슬레이트) — 기록이 끊긴 곳을 능선 위에 표시
  let band='';if(D.gap){const gx=rX(D.gap[0]),gw=rX(D.gap[1])-gx;
    band='<rect x="'+gx.toFixed(1)+'" y="0" width="'+gw.toFixed(1)+'" height="100" fill="rgba(125,155,181,.13)"/>';}
  // 컷 점: 사진/영상 = 심박색 채움(몸의 기록), 플라이오버 = 속 빈 원(지도의 시선)
  const drawn={};
  let dots=PH.map((p,i)=>{
    if(drawn[p.km])return '';drawn[p.km]=1;            // 겹친 컷은 점 하나로 병합
    const cx=rX(p.km).toFixed(1),cy=rY(rEleAt(p.km)).toFixed(1),g=stackOf(i);
    if(p.t==='f')return '<circle cx="'+cx+'" cy="'+cy+'" r="3" fill="none" stroke="#7d9bb5" stroke-width="1.4" opacity="0.85"/>';
    const c=hrHex(p.hr),r=g.some(j=>PH[j].t==='v')?3.2:2.4;   // 묶음에 영상이 있으면 영상 크기로
    const ring=g.length>1                                      // 여러 컷이 겹친 자리는 테두리를 둘러 표시
      ?'<circle cx="'+cx+'" cy="'+cy+'" r="'+(r+2.4)+'" fill="none" stroke="'+c+'" stroke-width="1" opacity="0.45"/>':'';
    // 촬영일 구분: 10월(본촬영)=원, 7월(답사)=마름모, 한 자리에 둘 다면 마름모 테두리 안에 원
    const days=new Set(g.map(j=>PH[j].d)),dia=(rr,f,st)=>'<rect x="'+(cx-rr)+'" y="'+(cy-rr)+'" width="'+(rr*2)+'" height="'+(rr*2)+'" transform="rotate(45 '+cx+' '+cy+')" fill="'+f+'" '+st+'/>';
    if(days.has(7)&&days.has(10))return ring+dia(r+1.2,'none','stroke="'+c+'" stroke-width="1.1" opacity="0.75"')+'<circle cx="'+cx+'" cy="'+cy+'" r="'+(r*0.7)+'" fill="'+c+'" opacity="0.9"/>';
    if(days.has(7))return ring+dia(r*0.92,c,'opacity="0.9"');
    return ring+'<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="'+c+'" opacity="0.9"/>';
  }).join('');
  rdg.innerHTML=band+'<path d="'+path+'" fill="none" stroke="#e6d8b2" stroke-width="2.2" opacity="0.85" vector-effect="non-scaling-stroke"/>'+dots;}
function moveMarker(km){if(!rmarker)return;rmarker.style.left=(km/D.total*W)+'px';}
buildRidge();

// ── 글리치 렌더 루프 ───────────────────────────────────────────
//  매 프레임 화면을 다시 그린다. 심박(intensity)과 컷 전환 순간(burst)에 따라
//  강도(I)가 정해지고, 이를 기반으로 RGB 채널 분리·흔들림·스캔라인·블록 노이즈를
//  합성해 "흔들린 기록" 느낌을 만든다. targetI()는 심박을 0~1 강도로 환산.
const rnd=(a,b)=>a+Math.random()*(b-a);
let TRAIL=true; // Trace Motion 샘플: 활동량만큼만 화면을 지워 잔상을 남긴다. 정지=선명, 전환·흔들림=잔상. T로 토글
function targetI(){if(cur<0)return 0;return Math.max(0,Math.min(1,(PH[cur].hr-120)/60));}
function frame(){requestAnimationFrame(frame);if(!started||!W||!H)return;  // 창이 0x0이면(탭 숨김·패널 접힘) 그리지 않는다
  if(mode==='video'&&vidReady&&vid.readyState>=2)rebuild(vid);
  if(!baseReady)return;
  intensity+=(targetI()-intensity)*0.07;if(burst>0)burst-=0.033;
  const I=Math.min(1,intensity*0.1+Math.max(0,burst)*0.9),B=Math.max(0,burst);
  ctx.setTransform(DPR,0,0,DPR,0,0);
  const clearA=TRAIL?Math.max(0.14,1-(B*0.86+I*0.34)):1; // 잔상 강도 = 전환(B)·심박(I). 켜져도 정지 땐 거의 풀클리어
  ctx.fillStyle='rgba(0,0,0,'+clearA+')';ctx.fillRect(0,0,W,H);
  const sh=I*9+B*28,vroll=(B>.3?rnd(-H*.3,H*.3):0);
  ctx.save();ctx.translate(rnd(-sh,sh),rnd(-sh,sh*.6)+vroll);
  const dx=2+I*20+B*34;ctx.globalCompositeOperation='lighter';
  ctx.drawImage(redC,-dx,rnd(-1.5,1.5),W,H);ctx.drawImage(cyanC,dx,rnd(-1.5,1.5),W,H);
  ctx.globalCompositeOperation='source-over';ctx.restore();
  const nt=Math.floor(I*8)+(B>0?7:0);
  for(let k=0;k<nt;k++){const sy=rnd(0,H),hh=rnd(3,24+I*44),ddx=(Math.random()-.5)*(I*W*.22+B*W*.5);ctx.drawImage(cv,0,sy*DPR,W*DPR,hh*DPR,ddx,sy,W,hh);}
  if(Math.random()<I*.5+B){const bw=rnd(40,W*.42),bh=rnd(10,64),sx=rnd(0,W-bw),sy=rnd(0,H-bh);ctx.drawImage(cv,sx*DPR,sy*DPR,bw*DPR,bh*DPR,sx+(Math.random()-.5)*(I*180+B*260),sy,bw,bh);}
  if(Math.random()<.3){const y=rnd(0,H);ctx.fillStyle='rgba(255,255,255,'+(.03+I*.08)+')';ctx.fillRect(0,y,W,rnd(1,3));}
  coordEl.style.textShadow=(-dx*.35)+'px 0 rgba(255,74,30,'+(.45+I*.5)+'),'+(dx*.35)+'px 0 rgba(38,220,255,'+(.45+I*.5)+')';
  coordEl.style.transform='translate('+rnd(-I*5,I*5)+'px,'+(vroll*.04)+'px)';
}
requestAnimationFrame(frame);

// ── 입력 처리 (드래그·키보드·자동재생) ────────────────────────
//  캔버스를 좌우로 드래그하거나(=거리 스크럽), ←/→ 키로 컷 이동.
//  idxFromX(): x좌표 → 가장 가까운 컷 인덱스. autoT는 3.2초 자동 넘김 타이머.
function idxFromX(x,tap){const r=Math.max(0,Math.min(1,x/W)),km=r*D.total;let b=0,bd=1e9;PH.forEach((p,i)=>{const d=Math.abs(p.km-km);if(d<bd){bd=d;b=i;}});
  const g=stackOf(b);if(g.length<2)return g[0];
  const k=g.indexOf(cur);
  if(k<0)return g[0];                    // 다른 자리에서 왔으면 묶음의 첫 컷
  return tap?g[(k+1)%g.length]:cur;}     // 같은 점을 다시 누르면 다음 컷 / 드래그 중엔 그대로
let down=false;
cv.addEventListener('pointerdown',e=>{down=true;setPhoto(idxFromX(e.clientX,true));moveMarker(e.clientX/W*D.total);hideHint();stopAuto();cv.setPointerCapture(e.pointerId);});
cv.addEventListener('pointermove',e=>{if(down){setPhoto(idxFromX(e.clientX));moveMarker(e.clientX/W*D.total);}});
cv.addEventListener('pointerup',()=>down=false);
addEventListener('keydown',e=>{if(e.key==='ArrowRight'){setPhoto(cur+1);hideHint();stopAuto();}if(e.key==='ArrowLeft'){setPhoto(cur-1);hideHint();stopAuto();}if(e.key==='t'||e.key==='T'){TRAIL=!TRAIL;}});
const hint=document.getElementById('hint');let hg=false;function hideHint(){if(!hg){hg=true;hint.style.opacity=0;}}
let autoT=null;function stopAuto(){if(autoT){clearInterval(autoT);autoT=null;}}
function startAuto(){autoT=setInterval(()=>setPhoto(cur>=PH.length-1?0:cur+1),3200);}
// 인트로 화면의 시작 버튼: 인트로를 숨기고 렌더 루프 가동, 첫 컷부터 자동재생 시작.
document.getElementById('go').addEventListener('click',()=>{document.getElementById('intro').classList.add('gone');started=true;resize();setPhoto(0);startAuto();});
resize(); // 초기 레이아웃 계산
